(1, 4, 20, 'Pull request submitted, awaiting review.', '2024-08-30 18:00:00'),
(2, 30, 8, 'Documentation updated to reflect new behavior.', '2025-03-12 23:00:00'),
(3, 34, 20, 'Not reproducible after latest deploy.', '2025-01-22 19:00:00'),
